using OcctSharp.MeshBoundaryDiagnostics;
using OcctSharp.PolyWorkspaces;
using OcctSharp.Tests.Shared;
using OcctSharp.Values;
namespace OcctSharp.Runtime.Tests;
public sealed class MeshBoundaryDiagnosticTests {
 static readonly int[] UnusedIndices=[4],IncidentIndices=[1,2,3];
 [Fact]public void FullExchangeMeshSourceAssociationAndActualVisibleWindowWorkflow()=>BatchBEMeshWorkflow.Run();
 [Fact]public void CopiedPolygonPreservesInputBoundsAndReportsSdkNormalization(){var points=new Point2d[]{new(0,0),new(2,0),new(2,3),new(0,0)};var result=MeshBoundaryComputations.Polygon2d(points,.05,-3);points[0]=new(99,99);Assert.Equal(-3,result.InputLower);Assert.Equal(0,result.InputUpper);Assert.Equal(1,result.NativeLower);Assert.Equal(4,result.NativeUpper);Assert.Equal(.05,result.Deflection);Assert.Equal(new Point2d(0,0),result.Points[0]);Assert.Equal(result.Points[0],result.Points[^1]);}
 [Fact]public void LazyPolygonBudgetDisposesWithoutPublishingAPrefix(){bool disposed=false;int visits=0;IEnumerable<Point2d> Input(){try{while(true){visits++;yield return new(visits,0);}}finally{disposed=true;}}Assert.Throws<ArgumentOutOfRangeException>(()=>MeshBoundaryComputations.Polygon2d(Input()));Assert.True(disposed);Assert.Equal(4097,visits);}
 [Fact]public void InvalidPolygonsCannotReachUninitializedNativeBuffers(){Assert.Throws<ArgumentOutOfRangeException>(()=>MeshBoundaryComputations.Polygon2d([new(0,0)]));Assert.ThrowsAny<Exception>(()=>MeshBoundaryComputations.Polygon2d([new(double.NaN,0),new(1,0)]));Assert.Throws<ArgumentOutOfRangeException>(()=>MeshBoundaryComputations.Polygon2d([new(0,0),new(1,0)],-1));Assert.Throws<ArgumentOutOfRangeException>(()=>MeshBoundaryComputations.Polygon2d([new(0,0),new(1,0)],lowerBound:int.MaxValue));}
 [Fact]public void EquilateralQualityAndNativeFreeNodeMappingReferToExactCopy(){var mesh=new AuthoredMesh([new(0,0,0),new(1,0,0),new(.5,Math.Sqrt(3)/2,0),new(9,9,9)],[new(0,1,2)]);using var data=PolyDataWorkspaces.FromMesh(mesh);using var native=data.CopyTriangulation();using var result=MeshBoundaryComputations.Analyze(native);var value=result.Diagnostic;Assert.Equal(4,value.NodeCount);Assert.Equal(3,value.BoundaryEdges);Assert.Equal(0,value.NonManifoldEdges);var triangle=Assert.Single(value.Triangles);Assert.Equal(1,triangle.Index);Assert.Equal(1,triangle.A);Assert.Equal(2,triangle.B);Assert.Equal(3,triangle.C);Assert.Equal(Math.Sqrt(3)/4,triangle.Area,12);Assert.Equal(1,triangle.Quality,12);Assert.Equal(UnusedIndices,value.UnreferencedNodeIndices);Assert.Equal(UnusedIndices,value.NativeFreeNodeIndices);using var copy=result.CopyTriangulation();native.Dispose();data.Dispose();result.Dispose();using var copied=PolyDataWorkspaces.Copy(copy);Assert.Equal(mesh.Triangles,copied.Mesh.Triangles);Assert.Equal(mesh.Positions,copied.Mesh.Positions);Assert.Equal(1,triangle.Quality,12);}
 [Fact]public void NonmanifoldEdgesReportAllIncidentTrianglesAndDoNotGuessCoherentAdjacency(){var mesh=new AuthoredMesh([new(0,0,0),new(1,0,0),new(0,1,0),new(0,-1,0),new(0,0,1)],[new(0,1,2),new(1,0,3),new(0,1,4)]);using var data=PolyDataWorkspaces.FromMesh(mesh);using var native=data.CopyTriangulation();using var result=MeshBoundaryComputations.Analyze(native);var value=result.Diagnostic;Assert.Equal(1,value.NonManifoldEdges);Assert.Equal(IncidentIndices,value.Edges.Single(x=>x.A==1&&x.B==2).TriangleIndices);Assert.Null(value.NativeFreeNodeIndices);Assert.Empty(value.UnreferencedNodeIndices);}
 [Fact]public void ReversedOrientationAndCollinearQualityRemainExplicitDiagnostics(){var mesh=new AuthoredMesh([new(0,0,0),new(1,0,0),new(0,1,0),new(0,-1,0)],[new(0,1,2),new(0,1,3)]);using var data=PolyDataWorkspaces.FromMesh(mesh);using var native=data.CopyTriangulation();using var result=MeshBoundaryComputations.Analyze(native);Assert.Equal(1,result.Diagnostic.InconsistentOrientationEdges);Assert.Null(result.Diagnostic.NativeFreeNodeIndices);var flat=new AuthoredMesh([new(0,0,0),new(1,0,0),new(2,0,0)],[new(0,1,2)]);using var flatData=PolyDataWorkspaces.FromMesh(flat);using var flatNative=flatData.CopyTriangulation();using var diagnostic=MeshBoundaryComputations.Analyze(flatNative);Assert.Equal(1,diagnostic.Diagnostic.DegenerateTriangles);Assert.Equal(0,diagnostic.Diagnostic.Triangles.Single().Quality);}
 [Fact]public void ExactFaceBoundaryReportsRealUvAndSignedNativeParametersAfterDisposal(){using var box=ShapeFactory.CreateBox(2,3,4);var result=MeshBoundaryComputations.FaceBoundary(box,0);Assert.Equal(0,result.FaceIndex);Assert.Equal(4,result.Edges.Count);Assert.All(result.Edges,row=>{Assert.NotNull(row.Range2d);Assert.NotNull(row.Range3d);Assert.NotNull(row.UvEnds);Assert.True(double.IsFinite(row.Range2d!.First));Assert.True(double.IsFinite(row.Range2d.Last));});Assert.InRange(result.MaximumTolerance,0,1e-3);box.Dispose();Assert.Equal(4,result.Edges.Count);}
 [Fact]public void WrongFaceAndExcessiveGraphIndicesNeverInferAnotherDomain(){using var box=ShapeFactory.CreateBox(2,3,4);Assert.Throws<ArgumentOutOfRangeException>(()=>MeshBoundaryComputations.FaceBoundary(box,-1));Assert.ThrowsAny<Exception>(()=>MeshBoundaryComputations.FaceBoundary(box,6));Assert.Throws<ArgumentOutOfRangeException>(()=>MeshBoundaryComputations.FaceBoundary(box,4096));}
 [Fact]public void MeshCopyBudgetIsAppliedBeforeAllocatingAnotherTriangulation(){var positions=Enumerable.Range(0,16385).Select(i=>new GpPoint(i,0,0)).ToArray();var mesh=new AuthoredMesh(positions,[new(0,1,2)]);using var data=PolyDataWorkspaces.FromMesh(mesh);using var native=data.CopyTriangulation();Assert.ThrowsAny<Exception>(()=>MeshBoundaryComputations.Analyze(native));}
 [Fact]public void IndependentMeshDiagnosticsDoNotShareMutableBuffers(){Parallel.For(0,8,_=>{var mesh=new AuthoredMesh([new(0,0,0),new(1,0,0),new(0,1,0)],[new(0,1,2)]);using var data=PolyDataWorkspaces.FromMesh(mesh);using var native=data.CopyTriangulation();using var result=MeshBoundaryComputations.Analyze(native);var value=result.Diagnostic;result.Dispose();Assert.Equal(3,value.BoundaryEdges);Assert.Equal(.5,value.Triangles.Single().Area);});}
}
